CREATE TABLE `CanteenSupplier` (`id` VARCHAR(191) NOT NULL,`organizationId` VARCHAR(191) NOT NULL,`schoolId` VARCHAR(191) NOT NULL,`name` VARCHAR(191) NOT NULL,`contactName` VARCHAR(191) NULL,`phone` VARCHAR(191) NULL,`email` VARCHAR(191) NULL,`address` TEXT NULL,`isActive` BOOLEAN NOT NULL DEFAULT true,`createdBy` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `CanteenSupplier_id_organizationId_schoolId_key` (`id`,`organizationId`,`schoolId`),UNIQUE INDEX `CanteenSupplier_schoolId_name_key` (`schoolId`,`name`),INDEX `CanteenSupplier_organizationId_schoolId_isActive_idx` (`organizationId`,`schoolId`,`isActive`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CanteenPurchaseOrder` (`id` VARCHAR(191) NOT NULL,`organizationId` VARCHAR(191) NOT NULL,`schoolId` VARCHAR(191) NOT NULL,`supplierId` VARCHAR(191) NOT NULL,`orderNumber` VARCHAR(191) NOT NULL,`status` VARCHAR(20) NOT NULL DEFAULT 'OPEN',`orderedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`expectedAt` DATETIME(3) NULL,`notes` TEXT NULL,`createdBy` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `CanteenPurchaseOrder_id_organizationId_schoolId_key` (`id`,`organizationId`,`schoolId`),UNIQUE INDEX `CanteenPurchaseOrder_schoolId_orderNumber_key` (`schoolId`,`orderNumber`),INDEX `CanteenPurchaseOrder_organizationId_schoolId_status_orderedAt_idx` (`organizationId`,`schoolId`,`status`,`orderedAt`),CONSTRAINT `CanteenPurchaseOrder_supplierId_organizationId_schoolId_fkey` FOREIGN KEY (`supplierId`,`organizationId`,`schoolId`) REFERENCES `CanteenSupplier`(`id`,`organizationId`,`schoolId`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CanteenPurchaseOrderLine` (`id` VARCHAR(191) NOT NULL,`organizationId` VARCHAR(191) NOT NULL,`schoolId` VARCHAR(191) NOT NULL,`purchaseOrderId` VARCHAR(191) NOT NULL,`stockItemId` VARCHAR(191) NOT NULL,`orderedQuantity` DECIMAL(12,3) NOT NULL,`receivedQuantity` DECIMAL(12,3) NOT NULL DEFAULT 0,`unitCost` DECIMAL(12,2) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `CanteenPurchaseOrderLine_id_organizationId_schoolId_key` (`id`,`organizationId`,`schoolId`),INDEX `CanteenPurchaseOrderLine_organizationId_schoolId_purchaseOrderId_idx` (`organizationId`,`schoolId`,`purchaseOrderId`),INDEX `CanteenPurchaseOrderLine_organizationId_schoolId_stockItemId_idx` (`organizationId`,`schoolId`,`stockItemId`),CONSTRAINT `CanteenPurchaseOrderLine_purchaseOrderId_organizationId_schoolId_fkey` FOREIGN KEY (`purchaseOrderId`,`organizationId`,`schoolId`) REFERENCES `CanteenPurchaseOrder`(`id`,`organizationId`,`schoolId`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CanteenStockLot` (`id` VARCHAR(191) NOT NULL,`organizationId` VARCHAR(191) NOT NULL,`schoolId` VARCHAR(191) NOT NULL,`stockItemId` VARCHAR(191) NOT NULL,`purchaseOrderId` VARCHAR(191) NULL,`purchaseOrderLineId` VARCHAR(191) NULL,`lotCode` VARCHAR(191) NOT NULL,`receivedQuantity` DECIMAL(12,3) NOT NULL,`remainingQuantity` DECIMAL(12,3) NOT NULL,`unit` VARCHAR(20) NOT NULL,`receivedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`expiryDate` DATETIME(3) NULL,`supplierName` VARCHAR(191) NULL,`notes` TEXT NULL,`createdBy` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `CanteenStockLot_id_organizationId_schoolId_key` (`id`,`organizationId`,`schoolId`),UNIQUE INDEX `CanteenStockLot_schoolId_stockItemId_lotCode_key` (`schoolId`,`stockItemId`,`lotCode`),INDEX `CanteenStockLot_organizationId_schoolId_expiryDate_idx` (`organizationId`,`schoolId`,`expiryDate`),INDEX `CanteenStockLot_organizationId_schoolId_stockItemId_remainingQuantity_idx` (`organizationId`,`schoolId`,`stockItemId`,`remainingQuantity`),CONSTRAINT `CanteenStockLot_stockItemId_organizationId_schoolId_fkey` FOREIGN KEY (`stockItemId`,`organizationId`,`schoolId`) REFERENCES `CanteenStockItem`(`id`,`organizationId`,`schoolId`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
